def experiment(inputs):
    scalar_divergence = 0
    # Simulate scalar vs pareto performance comparison
    for trial in range(inputs.get('trials', 1000)):
        scalar_perf = simulate_scalar(trial)
        pareto_perf = simulate_pareto(trial)
        if abs(scalar_perf - pareto_perf) > 0.05:
            scalar_divergence += 1
    return {'measurements': {'scalar_divergence': [scalar_divergence / 1000]}}

